using System.Security.Cryptography;

namespace MyDownloadManager.Tests.Infrastructure;

/// <summary>Content served by the test server. All test data is generated by the tests themselves.</summary>
public abstract class TestContent
{
    public abstract long Length { get; }
    public string ETag { get; init; } = "\"" + Guid.NewGuid().ToString("N") + "\"";
    public DateTimeOffset LastModified { get; init; } = new(2026, 1, 1, 0, 0, 0, TimeSpan.Zero);
    public abstract void Fill(long offset, Span<byte> destination);

    public string Sha256()
    {
        using var h = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
        var buf = new byte[1 << 20];
        for (long pos = 0; pos < Length; pos += buf.Length)
        {
            var n = (int)Math.Min(buf.Length, Length - pos);
            Fill(pos, buf.AsSpan(0, n));
            h.AppendData(buf, 0, n);
        }
        return Convert.ToHexStringLower(h.GetHashAndReset());
    }
}

public sealed class BytesContent(byte[] data) : TestContent
{
    public byte[] Data { get; } = data;
    public override long Length => Data.LongLength;
    public override void Fill(long offset, Span<byte> destination) => Data.AsSpan((int)offset, destination.Length).CopyTo(destination);

    public static BytesContent Random(int length, int seed)
    {
        var b = new byte[length];
        new Random(seed).NextBytes(b);
        return new BytesContent(b);
    }
}

/// <summary>Procedurally generated content of arbitrary size (multi-GB) without holding it in memory.</summary>
public sealed class GeneratedContent(long length, ulong seed) : TestContent
{
    public override long Length => length;

    public override void Fill(long offset, Span<byte> destination)
    {
        for (var i = 0; i < destination.Length; i++)
        {
            var pos = (ulong)(offset + i);
            var x = (pos >> 3) * 0x9E3779B97F4A7C15UL ^ seed;
            x ^= x >> 31; x *= 0xBF58476D1CE4E5B9UL; x ^= x >> 27;
            destination[i] = (byte)(x >> (int)((pos & 7) * 8));
        }
    }
}
